/* @lc app=leetcode id=3574 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun maxGCDScore(nums: IntArray, k: Int): Long = nums.indices.maxOf { i -> (i until nums.size).fold(listOf(0L, 100, 0L, 0L)) { st, j -> g(st[0], nums[j].toLong()).let { gg -> Integer.numberOfTrailingZeros(nums[j]).toLong().let { v -> (if (v < st[1]) 1L to v else if (v == st[1]) st[2] + 1 to v else st[2] to st[1]).let { (c, mv) -> listOf(gg, mv, c, maxOf(st[3], (j - i + 1).toLong() * gg * (if (c <= k) 2 else 1))) } } } }.let { it[3] } } }